"use strict";
import { MismatchToastItem } from "components/Popups/MismatchToastItem";
import {
  FailedNetworkSwitchPopup,
  TransactionPopupContent,
  UniswapXOrderPopupContent
} from "components/Popups/PopupContent";
import { ToastRegularSimple } from "components/Popups/ToastRegularSimple";
import { PopupType } from "components/Popups/types";
import { useAccount } from "hooks/useAccount";
import { useTranslation } from "react-i18next";
import { Flex, Text } from "ui/src";
import { Shuffle } from "ui/src/components/icons/Shuffle";
import { NetworkLogo } from "uniswap/src/components/CurrencyLogo/NetworkLogo";
import { getChainInfo } from "uniswap/src/features/chains/chainInfo";
import { useSupportedChainId } from "uniswap/src/features/chains/hooks/useSupportedChainId";
import { SwapTab } from "uniswap/src/types/screens/interface";
export function PopupItem({ content, onClose }) {
  const { t } = useTranslation();
  const { chainId } = useAccount();
  const supportedChainId = useSupportedChainId(chainId);
  const ToastGenerator = ({
    type,
    icon,
    title,
    description,
    onDismiss
  }) => {
    return <ToastRegularSimple
      onDismiss={onDismiss}
      icon={<div style={{ color: type === "success" ? "#4CAF50" : "#f44336", fontSize: "20px" }}>{icon}</div>}
      text={<Flex flexDirection="column" gap="$gap4" flex={1}>
            <Text variant="body2" color="$neutral1">
              {title}
            </Text>
            <Text variant="body3" color="$neutral2">
              {description}
            </Text>
          </Flex>}
    />;
  };
  switch (content.type) {
    case PopupType.Transaction: {
      return supportedChainId ? <TransactionPopupContent hash={content.hash} chainId={supportedChainId} onClose={onClose} /> : null;
    }
    case PopupType.Order: {
      return <UniswapXOrderPopupContent orderHash={content.orderHash} onClose={onClose} />;
    }
    case PopupType.FailedSwitchNetwork: {
      return <FailedNetworkSwitchPopup chainId={content.failedSwitchNetwork} onClose={onClose} />;
    }
    case PopupType.SwitchNetwork: {
      return <ToastRegularSimple
        onDismiss={onClose}
        icon={<NetworkLogo chainId={content.chainId} />}
        text={getSwitchNetworkTitle(t, content.action, content.chainId)}
      />;
    }
    case PopupType.Bridge: {
      return <ToastRegularSimple
        onDismiss={onClose}
        icon={<BridgeToast inputChainId={content.inputChainId} outputChainId={content.outputChainId} />}
      />;
    }
    case PopupType.Mismatch: {
      return <MismatchToastItem onDismiss={onClose} />;
    }
    case PopupType.LiquiditySuccess: {
      return <ToastGenerator
        type="success"
        onDismiss={onClose}
        icon={<span>✓</span>}
        title={content.content.title}
        description={content.content.description}
      />;
    }
    case PopupType.LiquidityError: {
      return <ToastGenerator
        type="error"
        onDismiss={onClose}
        icon={<span>✗</span>}
        title={content.content.title}
        description={content.content.description}
      />;
    }
    case PopupType.LockSuccess: {
      return <ToastGenerator
        type="success"
        onDismiss={onClose}
        icon={<span>🔒</span>}
        title={content.content.title}
        description={content.content.description}
      />;
    }
    case PopupType.LockError: {
      return <ToastGenerator
        type="error"
        onDismiss={onClose}
        icon={<span>🔒</span>}
        title={content.content.title}
        description={content.content.description}
      />;
    }
    case PopupType.VotingSuccess: {
      return <ToastGenerator
        type="success"
        onDismiss={onClose}
        icon={<span>🗳️</span>}
        title={content.content.title}
        description={content.content.description}
      />;
    }
    case PopupType.VotingError: {
      return <ToastGenerator
        onDismiss={onClose}
        type="error"
        icon={<span>🗳️</span>}
        title={content.content.title}
        description={content.content.description}
      />;
    }
    case PopupType.IncentiveSuccess: {
      return <ToastGenerator
        onDismiss={onClose}
        type="success"
        icon={<span>💰</span>}
        title={content.content.title}
        description={content.content.description}
      />;
    }
    case PopupType.IncentiveError: {
      return <ToastGenerator
        type="error"
        onDismiss={onClose}
        icon={<span>💰</span>}
        title={content.content.title}
        description={content.content.description}
      />;
    }
    case PopupType.StakeSuccess: {
      return <ToastGenerator
        type="success"
        onDismiss={onClose}
        icon={<span>📈</span>}
        title={content.content.title}
        description={content.content.description}
      />;
    }
    case PopupType.StakeError: {
      return <ToastGenerator
        type="error"
        onDismiss={onClose}
        icon={<span>📈</span>}
        title={content.content.title}
        description={content.content.description}
      />;
    }
    case PopupType.UnstakeSuccess: {
      return <ToastGenerator
        type="success"
        onDismiss={onClose}
        icon={<span>📉</span>}
        title={content.content.title}
        description={content.content.description}
      />;
    }
    case PopupType.UnstakeError: {
      return <ToastGenerator
        type="error"
        onDismiss={onClose}
        icon={<span>📉</span>}
        title={content.content.title}
        description={content.content.description}
      />;
    }
    case PopupType.ClaimRewardsSuccess: {
      return <ToastGenerator
        type="error"
        onDismiss={onClose}
        icon={<span>🎉</span>}
        title={content.content.title}
        description={content.content.description}
      />;
    }
    case PopupType.ClaimRewardsError: {
      return <ToastGenerator
        type="error"
        onDismiss={onClose}
        icon={<span>🎉</span>}
        title={content.content.title}
        description={content.content.description}
      />;
    }
    case PopupType.ClaimFeesSuccess: {
      return <ToastGenerator
        type="success"
        onDismiss={onClose}
        icon={<span>💸</span>}
        title={content.content.title}
        description={content.content.description}
      />;
    }
    case PopupType.ClaimFeesError: {
      return <ToastGenerator
        type="error"
        onDismiss={onClose}
        icon={<span>💸</span>}
        title={content.content.title}
        description={content.content.description}
      />;
    }
  }
}
function getSwitchNetworkTitle(t, action, chainId) {
  const { label } = getChainInfo(chainId);
  switch (action) {
    case SwapTab.Swap:
      return t("notification.swap.network", { network: label });
    case SwapTab.Send:
      return t("notification.send.network", { network: label });
    default:
      return "";
  }
}
function BridgeToast({
  inputChainId,
  outputChainId
}) {
  const originChain = getChainInfo(inputChainId);
  const targetChain = getChainInfo(outputChainId);
  return <Flex row gap="$gap8">
      <Flex row gap="$gap4">
        <NetworkLogo chainId={inputChainId} />
        <Text variant="body2" lineHeight={20}>
          {originChain.label}
        </Text>
      </Flex>
      <Shuffle color="$neutral2" size="$icon.20" />
      <Flex row gap="$gap4">
        <NetworkLogo chainId={outputChainId} />
        <Text variant="body2" lineHeight={20}>
          {targetChain.label}
        </Text>
      </Flex>
    </Flex>;
}
